import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

import { describe, expect, it } from 'vitest'

import { EngineSpec, checkSpec, validateSpec } from '../src'
import { explore, leakIssues, minOpenAtFinal } from './fixtures/explorer'
import { referenceIssues } from './fixtures/refs'

const ROOT = resolve(import.meta.dirname, '../../..')
const PATH = resolve(ROOT, 'fixtures/generated/singapore-1819.json')
const generated = EngineSpec.parse(JSON.parse(readFileSync(PATH, 'utf8')))

/** A spec generated by `packages/generation/scripts/generate-v3.ts` from the 1819 handout (#218, #219). */
describe('generated singapore-1819', () => {
  it('passes spec-v3 with no errors, and every reference resolves', () => {
    expect(validateSpec(JSON.parse(readFileSync(PATH, 'utf8'))).ok).toBe(true)
    expect(checkSpec(generated).errors).toEqual([])
    expect(referenceIssues(generated)).toEqual([])
  })

  it('every ending is reachable, two stay open at the end, and no view leaks', async () => {
    const result = await explore(generated, leakIssues)
    expect([...result.endings.keys()].sort(), `explored ${result.states} states`).toEqual(generated.endings.map((ending) => ending.id).sort())
    expect(result.leaks).toEqual([])
    expect(Math.min(...result.openAtFinal)).toBeGreaterThanOrEqual(2)
    expect(minOpenAtFinal(generated)).toBeGreaterThanOrEqual(2)
  }, 120_000)
})
